 "decisions": [
  {
   "title": "Same database, tables stay where they are",
   "context": "The legacy page reads and writes CUENTAS and TRANSFERENCIAS in BancoFicticio through inline SQL; there are no stored procedures to call.",
   "decision": "data_strategy is same_database: the service uses the legacy tables and columns as they are, with the legacy precision (CTA_SALDO decimal(13,2), TRF_MONTO decimal(11,2), TRF_COMISION decimal(7,2)).",
   "consequences": "No data migration. The golden master traces can be replayed against the same schema."
  },
  {
   "title": "Transaction boundary and status returned as data",
   "context": "btnTransferir_Click opens a transaction at line 34, rolls it back at lines 43, 52, 62 and 70 and commits at line 102. Its error exits return a message and still return outputs; the traces show returns 0 or -1 with lblMensaje.",
   "decision": "RealizarTransferencia declares an output with legacy 'return' (0 on success, -1 on any rejection) plus mensaje, comision and numero, so every path returns the status and the outputs as the legacy does. The four rollback points are named in the errors of the use case (ORIGEN_NO_EXISTE, ORIGEN_INACTIVA, DESTINO_NO_EXISTE, SALDO_INSUFICIENTE, legacy code -1, with the legacy message) only to identify the outcome of each rollback in the unit of work; the service answers them as an ordinary response with status -1 and the legacy message, not as an exception. The UnitOfWork port has begin, commit and rollback, and the service calls them where the legacy does. The same-account rejection (RULE-005) happens before the transaction begins, with no database access and no rollback.",
   "consequences": "A rejection is a normal response with status -1 and the legacy message; the work is undone only after the transaction began. There are no savepoints."
  },
  {
   "title": "Commission logic is shared, not a port",
   "context": "ComisionService.Calcular is a pure static function, with no database access.",
   "decision": "It is ported as the use case CalcularComision (RULE-001..003), exposed on its own, and the same domain function is used inside RealizarTransferencia to compute the commission for the balance check (RULE-008), the posting (RULE-009) and the record (RULE-010). It is not a port.",
   "consequences": "There is a single implementation of the rounding (half away from zero), the cap before the INM surcharge, and the exact case-sensitive match of 'INM'."
  },
  {
   "title": "Redirect becomes data",
   "context": "After the commit the page sets lblComision and lblMensaje and redirects to Comprobante.aspx?numero=n, so those labels are never displayed on the page.",
   "decision": "The service returns comision (formatted '0.00'), the message 'TRANSFERENCIA REALIZADA' and numero as outputs, which is what the traces observe. The client navigates to GET /comprobantes/{numero}.",
   "consequences": "The new number is delivered to the client explicitly. No behaviour of the legacy is lost."
  },
  {
   "title": "Sequential number MAX+1 kept",
   "context": "The transfer number is ISNULL(MAX(TRF_NUMERO),0)+1, read inside the transaction.",
   "decision": "The behaviour is kept as the legacy defines it, with no sequence or isolation changes.",
   "consequences": "Two concurrent transfers can compute the same number as in the legacy; the primary key makes the second fail. Hardening is a separate decision outside this migration."
  },
  {
   "title": "UI validators stay in the front end",
   "context": "The .aspx has validators (required fields, 10-digit origin, amount range 1 to 10000) that are not part of the approved business rules.",
   "decision": "They are presentation concerns and are not translated into the service use cases. Input lengths (10, 10, 9) are kept in the input types.",
   "consequences": "The service enforces only the approved rules. Input range checks belong to the new front end."
  }
 ],
 "masks": [],
 "infrastructure": [],
 "data_strategy": "same_database"
}

Rules:
[
 {
  "id": "RULE-001",
  "name": "Base commission: flat fee up to 1000, otherwise 0.1% of amount",
  "category": "calculation",
  "priority": "P0",
  "statement": "Operations of 1000.00 or less pay a flat commission of 0.50. Operations above 1000.00 pay 0.1% of the amount, rounded to 2 decimals with midpoints rounded away from zero.",
  "condition": "monto <= 1000 -> flat fee; monto > 1000 -> percentage fee",
  "action": "If monto <= 1000.00, comision = 0.50. Otherwise comision = Round(monto * 0.001, 2, AwayFromZero).",
  "inputs": [
   {
    "name": "monto",
    "type": "decimal(19,4,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "comision (base)",
    "type": "decimal(19,4,signed)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Amount at the flat-fee limit\n  Given monto is 1000.00\n  When the commission is calculated\n  Then the base commission is 0.50",
   "Scenario: Amount above the limit\n  Given monto is 2500.00\n  When the commission is calculated\n  Then the base commission is 2.50",
   "Scenario: Midpoint rounding\n  Given monto is 1500.50\n  When the commission is calculated\n  Then 1500.50 * 0.001 = 1.5005 is rounded to 1.50",
   "Scenario: Just above the limit\n  Given monto is 1000.01\n  When the commission is calculated\n  Then the base commission is 1.00"
  ],
  "sources": [
   {
    "file": "App_Code/ComisionService.cs",
    "line_start": 10,
    "line_end": 10
   }
  ]
 },
 {
  "id": "RULE-002",
  "name": "Commission cap of 5.00 before surcharge",
  "category": "policy",
  "priority": "P0",
  "statement": "If the calculated commission (comision) exceeds 5.00, it is set to 5.00.",
  "condition": "comision > 5.00",
  "action": "Set comision = 5.00.",
  "inputs": [
   {
    "name": "comision (base)",
    "type": "decimal(19,4,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "comision (capped)",
    "type": "decimal(19,4,signed)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Commission above the cap\n  Given monto is 20000.00 and the base commission is 20.00\n  When the cap is applied\n  Then the commission is 5.00",
   "Scenario: Commission exactly at the cap\n  Given monto is 5000.00 and the base commission is 5.00\n  When the cap is applied\n  Then the commission stays 5.00",
   "Scenario: Commission below the cap\n  Given monto is 3000.00 and the base commission is 3.00\n  When the cap is applied\n  Then the commission stays 3.00"
  ],
  "sources": [
   {
    "file": "App_Code/ComisionService.cs",
    "line_start": 11,
    "line_end": 14
   }
  ]
 },
 {
  "id": "RULE-003",
  "name": "Surcharge of 1.00 for type INM, applied after the cap",
  "category": "calculation",
  "priority": "P0",
  "statement": "Operations of type \"INM\" pay an extra 1.00 on top of the capped commission. The surcharge is not subject to the 5.00 cap, so an INM operation can pay up to 6.00.",
  "condition": "tipo == \"INM\" (exact, case-sensitive match)",
  "action": "comision = comision + 1.00, after the cap has been applied. The result is returned.",
  "inputs": [
   {
    "name": "tipo",
    "type": "text(var,max,utf8)",
    "description": ""
   },
   {
    "name": "comision (capped)",
    "type": "decimal(19,4,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "comision (final)",
    "type": "decimal(19,4,signed)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: INM operation with small amount\n  Given monto is 500.00 and tipo is \"INM\"\n  When the commission is calculated\n  Then the commission is 1.50",
   "Scenario: INM operation above the cap\n  Given monto is 10000.00 and tipo is \"INM\"\n  When the commission is calculated\n  Then the capped commission 5.00 plus 1.00 gives 6.00",
   "Scenario: Other type\n  Given monto is 500.00 and tipo is \"XYZ\"\n  When the commission is calculated\n  Then the commission is 0.50"
  ],
