    7  public partial class Transferencia : Page
    8  {
    9      protected void Page_Load(object sender, EventArgs e)
   10      {
   11          if (!IsPostBack)
   12          {
   13              lblMensaje.Text = string.Empty;
   14          }
   15      }
   16  
   17      protected void btnTransferir_Click(object sender, EventArgs e)
   18      {
   19          string origen = txtCuentaOrigen.Text.Trim();
   20          string destino = txtCuentaDestino.Text.Trim();
   21          decimal monto = decimal.Parse(txtMonto.Text);
   22          string tipo = ddlTipo.SelectedValue;
   23  
   24          if (origen == destino)
   25          {
   26              lblMensaje.Text = "LA CUENTA DESTINO ES LA MISMA";
   27              return;
   28          }
   29  
   30          string conexion = ConfigurationManager.ConnectionStrings["Banco"].ConnectionString;
   31          using (SqlConnection cn = new SqlConnection(conexion))
   32          {
   33              cn.Open();
   34              SqlTransaction tx = cn.BeginTransaction();
   35  
   36              SqlCommand leer = new SqlCommand(
   37                  "SELECT CTA_ESTADO, CTA_SALDO FROM CUENTAS WHERE CTA_NUMERO = @cuenta", cn, tx);
   38              leer.Parameters.AddWithValue("@cuenta", origen);
   39              SqlDataReader r = leer.ExecuteReader();
   40              if (!r.Read())
   41              {
   42                  r.Close();
   43                  tx.Rollback();
   44                  lblMensaje.Text = "CUENTA ORIGEN NO EXISTE";
   45                  return;
   46              }
   47              string estado = r.GetString(0);
   48              decimal saldo = r.GetDecimal(1);
   49              r.Close();
   50              if (estado != "A")
   51              {
   52                  tx.Rollback();
   53                  lblMensaje.Text = "CUENTA ORIGEN INACTIVA";
   54                  return;
   55              }
   56  
   57              SqlCommand existe = new SqlCommand(
   58                  "SELECT COUNT(*) FROM CUENTAS WHERE CTA_NUMERO = @cuenta AND CTA_ESTADO = 'A'", cn, tx);
   59              existe.Parameters.AddWithValue("@cuenta", destino);
   60              if ((int)existe.ExecuteScalar() == 0)
   61              {
   62                  tx.Rollback();
   63                  lblMensaje.Text = "CUENTA DESTINO NO EXISTE";
   64                  return;
   65              }
   66  
   67              decimal comision = ComisionService.Calcular(monto, tipo);
   68              if (saldo < monto + comision)
   69              {
   70                  tx.Rollback();
   71                  lblMensaje.Text = "SALDO INSUFICIENTE";
   72                  return;
   73              }
   74  
   75              SqlCommand debitar = new SqlCommand(
   76                  "UPDATE CUENTAS SET CTA_SALDO = CTA_SALDO - @valor WHERE CTA_NUMERO = @cuenta", cn, tx);
   77              debitar.Parameters.AddWithValue("@valor", monto + comision);
   78              debitar.Parameters.AddWithValue("@cuenta", origen);
   79              debitar.ExecuteNonQuery();
   80  
   81              SqlCommand acreditar = new SqlCommand(
   82                  "UPDATE CUENTAS SET CTA_SALDO = CTA_SALDO + @valor WHERE CTA_NUMERO = @cuenta", cn, tx);
   83              acreditar.Parameters.AddWithValue("@valor", monto);
   84              acreditar.Parameters.AddWithValue("@cuenta", destino);
   85              acreditar.ExecuteNonQuery();
   86  
   87              SqlCommand siguiente = new SqlCommand(
   88                  "SELECT ISNULL(MAX(TRF_NUMERO), 0) + 1 FROM TRANSFERENCIAS", cn, tx);
   89              int numero = (int)siguiente.ExecuteScalar();
   90  
   91              SqlCommand registrar = new SqlCommand(
   92                  "INSERT INTO TRANSFERENCIAS (TRF_NUMERO, TRF_ORIGEN, TRF_DESTINO, TRF_MONTO, TRF_COMISION, TRF_TIPO) " +
   93                  "VALUES (@numero, @origen, @destino, @monto, @comision, @tipo)", cn, tx);
   94              registrar.Parameters.AddWithValue("@numero", numero);
   95              registrar.Parameters.AddWithValue("@origen", origen);
   96              registrar.Parameters.AddWithValue("@destino", destino);
   97              registrar.Parameters.AddWithValue("@monto", monto);
   98              registrar.Parameters.AddWithValue("@comision", comision);
   99              registrar.Parameters.AddWithValue("@tipo", tipo);
  100              registrar.ExecuteNonQuery();
  101  
  102              tx.Commit();
  103              lblComision.Text = comision.ToString("0.00");
  104              lblMensaje.Text = "TRANSFERENCIA REALIZADA";
  105              Response.Redirect("Comprobante.aspx?numero=" + numero);
  106          }
  107      }
