Behaviour comes from the legacy program, form from the design. Before any rule, apply the defaults and normalizations the program applies to its parameters (isnull, coalesce, set). Keep the same order of calls to external programs with the same arguments; leave outputs NULL where the program leaves them NULL; raise errors only where the program raises them, with its codes and messages; keep every predicate of its SQL (every column of a WHERE, the same IN lists, the same parameters). Ports that replace legacy programs are stubs in the verification: their adapters do not run. The service is where inputs are defaulted and the branch is chosen; a repository runs exactly the SQL of the program for its entity.

response.content:
```csharp
using Bancoficticio.Transferencias.Adapters.In.Rest;

namespace Bancoficticio.Transferencias.Application;

/// <summary>Use case CalcularComision (legacy ComisionService.Calcular, RULE-001..003).</summary>
public sealed class CalcularComisionService
{
    public CalcularComisionResponse Execute(CalcularComisionRequest request)
    {
        // The legacy parameter is a non-nullable decimal: a missing amount has no legacy
        // counterpart, so it is not defaulted; reading .Value throws on null.
        decimal monto = request.Monto!.Value;
        string? tipo = request.Tipo;

        // RULE-001
        decimal comision = monto <= 1000m
            ? 0.50m
            : Math.Round(monto * 0.001m, 2, MidpointRounding.AwayFromZero);

        // RULE-002
        if (comision > 5.00m)
        {
            comision = 5.00m;
        }

        // RULE-003 (exact, case-sensitive ordinal match; null never matches)
        if (tipo == "INM")
        {
            comision += 1.00m;
        }

        return new CalcularComisionResponse(comision);
    }
}
